BEGIN;
-- Provision with a dedicated migration owner. The runtime role is deliberately NOLOGIN.
DO $$ BEGIN
 IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname='wholesale_runtime') THEN
   CREATE ROLE wholesale_runtime NOLOGIN NOSUPERUSER NOCREATEDB NOCREATEROLE NOBYPASSRLS;
 END IF;
 IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname='wholesale_runtime' AND (rolsuper OR rolbypassrls OR rolcreaterole OR rolcreatedb OR rolcanlogin)) THEN RAISE EXCEPTION 'Unsafe runtime role'; END IF;
END $$;
DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname=current_user AND (rolsuper OR rolbypassrls)) THEN RAISE EXCEPTION 'migration owner must have BYPASSRLS for protected definer functions'; END IF; END $$;
REVOKE CREATE ON SCHEMA public FROM PUBLIC;
REVOKE ALL ON SCHEMA app_private FROM PUBLIC;
GRANT USAGE ON SCHEMA app_private TO wholesale_runtime;
-- These GUC values are supplied by trusted server code, never by untrusted client SQL.
CREATE FUNCTION app_private.tenant() RETURNS uuid LANGUAGE sql STABLE AS $$ SELECT nullif(current_setting('app.tenant_id',true),'')::uuid $$;
CREATE FUNCTION app_private.actor() RETURNS uuid LANGUAGE sql STABLE AS $$ SELECT nullif(current_setting('app.membership_id',true),'')::uuid $$;
CREATE FUNCTION app_private.can(t uuid, s uuid, p text) RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
 SELECT t=app_private.tenant() AND EXISTS (
  SELECT 1 FROM organizations.membership m JOIN identity.principal u ON u.id=m.principal_id
  JOIN organizations.tenant te ON te.id=m.tenant_id
  JOIN "authorization".assignment a ON a.tenant_id=m.tenant_id AND a.membership_id=m.id
  JOIN "authorization".role r ON r.tenant_id=a.tenant_id AND r.id=a.role_id
  JOIN "authorization".role_permission rp ON rp.tenant_id=r.tenant_id AND rp.role_id=r.id
  WHERE m.tenant_id=t AND m.id=app_private.actor() AND m.status='ACTIVE' AND m.archived_at IS NULL
  AND u.status='ACTIVE' AND u.archived_at IS NULL AND te.status='ACTIVE' AND te.archived_at IS NULL
  AND a.archived_at IS NULL AND r.archived_at IS NULL AND rp.archived_at IS NULL
  AND (a.valid_until IS NULL OR a.valid_until>now()) AND rp.permission=p
  AND (a.assigned_scope_id IS NULL OR (s IS NOT NULL AND a.assigned_scope_id=s AND EXISTS
      (SELECT 1 FROM organizations.scope x WHERE x.tenant_id=t AND x.id=s AND x.archived_at IS NULL)))
 )
$$;
-- Owner must be trusted and able to read authorization tables despite FORCE RLS.
-- On a standard PostgreSQL installation run migrations with a dedicated superuser/migration administrator.
-- Managed hosts must certify equivalent dedicated BYPASSRLS ownership before use.
CREATE FUNCTION app_private.require_permission(t uuid,s uuid,p text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
BEGIN IF NOT coalesce(app_private.can(t,s,p),false) THEN RAISE EXCEPTION 'permission denied: %',p USING ERRCODE='42501'; END IF; END $$;
CREATE FUNCTION app_private.touch() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog,pg_temp AS $$
BEGIN
 IF NEW.id<>OLD.id THEN RAISE EXCEPTION 'immutable id'; END IF;
 IF to_jsonb(NEW)->>'tenant_id' IS DISTINCT FROM to_jsonb(OLD)->>'tenant_id' THEN RAISE EXCEPTION 'immutable tenant'; END IF;
 IF to_jsonb(NEW)->>'scope_id' IS DISTINCT FROM to_jsonb(OLD)->>'scope_id' THEN RAISE EXCEPTION 'scope reassignment requires dedicated workflow'; END IF;
 NEW.created_at=OLD.created_at; NEW.version=OLD.version+1; NEW.updated_at=clock_timestamp(); RETURN NEW;
END $$;
CREATE FUNCTION app_private.deny_mutation() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog,pg_temp AS $$ BEGIN RAISE EXCEPTION 'append-only record' USING ERRCODE='55000'; END $$;
CREATE FUNCTION app_private.redact(j jsonb) RETURNS jsonb LANGUAGE sql IMMUTABLE SET search_path=pg_catalog,pg_temp AS $$
 SELECT j - ARRAY['object_key','payload_key','secret_ref','token_digest','challenge_digest','public_key','credential_id','capture_evidence','evidence','evidence_key','payload','tax_id','registration_no','phone','display_name','point','landmark','neighborhood','shop_name','received_by','beneficiary_ref','merchant_ref','proposed_changes','request','terms','body','configuration','decision_reason','reason','memo','name_en','name_ar','name_ku','name','address_id','before_data','after_data','object_key','provider_ref','verified_provider_ref','source_ref','sha256','alias','normalized','search_text','ingredients','rules','policy_snapshot','discount_bps','payload_digest','request_hash','payload_hash','correlation_id']::text[]
$$;
CREATE FUNCTION app_private.capture_audit() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE b jsonb; a jsonb; t uuid; sc uuid; rid uuid; eid uuid:=gen_random_uuid(); ts timestamptz:=clock_timestamp(); h text; actor uuid:=app_private.actor(); corr text:=nullif(current_setting('app.correlation_id',true),'');
BEGIN
 IF TG_OP<>'INSERT' THEN b=app_private.redact(to_jsonb(OLD)); END IF;
 IF TG_OP<>'DELETE' THEN a=app_private.redact(to_jsonb(NEW)); END IF;
 t=(coalesce(a,b)->>'tenant_id')::uuid; sc=(coalesce(a,b)->>'scope_id')::uuid; rid=(coalesce(a,b)->>'id')::uuid;
 h=encode(public.digest(convert_to(jsonb_build_array(eid,t,sc,actor,TG_TABLE_SCHEMA||'.'||TG_TABLE_NAME,rid,TG_OP,b,a,corr,ts)::text,'UTF8'),'sha256'),'hex');
 INSERT INTO audit.event(id,tenant_id,scope_id,actor_id,resource,resource_id,action,before_data,after_data,correlation_id,event_hash,created_at,updated_at)
 VALUES(eid,t,sc,actor,TG_TABLE_SCHEMA||'.'||TG_TABLE_NAME,rid,TG_OP,b,a,corr,h,ts,ts);
 RETURN NULL;
END $$;

