-- Unapproved or indicative exchange rates may not be stamped on commercial documents.
CREATE FUNCTION app_private.check_fx() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
BEGIN IF NEW.fx_rate_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM treasury.fx_rate f WHERE f.tenant_id=NEW.tenant_id AND f.id=NEW.fx_rate_id AND f.status='APPROVED' AND f.kind IN ('OFFICIAL','ACCOUNTING','AUTHORIZED_TRANSACTION') AND (f.kind<>'AUTHORIZED_TRANSACTION' OR EXISTS (SELECT 1 FROM compliance.policy p WHERE p.tenant_id=NEW.tenant_id AND p.code='AUTHORIZED_FX_CHECKOUT' AND p.status='ACTIVE' AND p.archived_at IS NULL AND p.effective_from<=now() AND (p.effective_to IS NULL OR p.effective_to>now()))) AND f.archived_at IS NULL AND f.effective_from<=now() AND (f.effective_to IS NULL OR f.effective_to>now())) THEN RAISE EXCEPTION 'FX rate not authorized or effective'; END IF; RETURN NEW; END $$;
CREATE TRIGGER quote_fx BEFORE INSERT OR UPDATE OF fx_rate_id ON commerce.quote FOR EACH ROW EXECUTE FUNCTION app_private.check_fx();
CREATE TRIGGER invoice_fx BEFORE INSERT OR UPDATE OF fx_rate_id ON commerce.invoice FOR EACH ROW EXECUTE FUNCTION app_private.check_fx();
CREATE FUNCTION app_private.freeze_final() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog,pg_temp AS $$
BEGIN IF OLD.status=TG_ARGV[0] THEN RAISE EXCEPTION 'finalized record is immutable'; END IF; IF TG_OP='DELETE' THEN RETURN OLD; END IF; RETURN NEW; END $$;
CREATE TRIGGER freeze_invoice BEFORE UPDATE OR DELETE ON commerce.invoice FOR EACH ROW EXECUTE FUNCTION app_private.freeze_final('ISSUED');
CREATE TRIGGER freeze_quote BEFORE UPDATE OR DELETE ON commerce.quote FOR EACH ROW EXECUTE FUNCTION app_private.freeze_final('ACCEPTED');
CREATE TRIGGER freeze_journal BEFORE UPDATE OR DELETE ON accounting.journal FOR EACH ROW EXECUTE FUNCTION app_private.freeze_final('POSTED');
CREATE FUNCTION app_private.freeze_child() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE j jsonb; st text; parent uuid; t uuid;
BEGIN
 -- lock both old and new parents if a line is reassigned; disallow reassignment entirely.
 IF TG_OP='UPDATE' AND (to_jsonb(OLD)->>TG_ARGV[2]) IS DISTINCT FROM (to_jsonb(NEW)->>TG_ARGV[2]) THEN RAISE EXCEPTION 'parent immutable'; END IF;
 j=CASE WHEN TG_OP='DELETE' THEN to_jsonb(OLD) ELSE to_jsonb(NEW) END; t=(j->>'tenant_id')::uuid; parent=(j->>TG_ARGV[2])::uuid;
 EXECUTE format('SELECT status FROM %I.%I WHERE tenant_id=$1 AND id=$2 FOR UPDATE',TG_ARGV[0],TG_ARGV[1]) INTO st USING t,parent;
 IF st=TG_ARGV[3] THEN RAISE EXCEPTION 'finalized parent lines are immutable'; END IF;
 IF TG_OP='DELETE' THEN RETURN OLD; END IF; RETURN NEW;
END $$;
CREATE TRIGGER freeze_journal_line BEFORE INSERT OR UPDATE OR DELETE ON accounting.journal_line FOR EACH ROW EXECUTE FUNCTION app_private.freeze_child('accounting','journal','journal_id','POSTED');
CREATE TRIGGER freeze_invoice_line BEFORE INSERT OR UPDATE OR DELETE ON commerce.invoice_line FOR EACH ROW EXECUTE FUNCTION app_private.freeze_child('commerce','invoice','invoice_id','ISSUED');
CREATE TRIGGER freeze_quote_line BEFORE INSERT OR UPDATE OR DELETE ON commerce.quote_line FOR EACH ROW EXECUTE FUNCTION app_private.freeze_child('commerce','quote','quote_id','ACCEPTED');
-- Ledger invariant enforced even on privileged posting, not merely in API code.
CREATE FUNCTION app_private.check_journal_post() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE deb numeric; cre numeric; n bigint;
BEGIN
 IF NEW.status<>'POSTED' THEN RETURN NEW; END IF;
 IF TG_OP='INSERT' THEN RAISE EXCEPTION 'create journal as draft first'; END IF;
 IF NEW.checker_id IS NULL OR NEW.checker_id=NEW.maker_id OR NEW.posted_at IS NULL THEN RAISE EXCEPTION 'independent approval required'; END IF;
 PERFORM 1 FROM accounting.period p WHERE p.tenant_id=NEW.tenant_id AND p.id=NEW.period_id AND p.ledger_id=NEW.ledger_id AND p.status='OPEN' AND NEW.entry_date BETWEEN p.starts_on AND p.ends_on FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'invalid or closed accounting period'; END IF;
 SELECT coalesce(sum(l.debit_minor),0),coalesce(sum(l.credit_minor),0),count(*) INTO deb,cre,n FROM accounting.journal_line l WHERE l.tenant_id=NEW.tenant_id AND l.journal_id=NEW.id;
 IF n<2 OR deb<>cre OR deb<=0 THEN RAISE EXCEPTION 'journal must balance'; END IF;
 IF EXISTS(SELECT 1 FROM accounting.journal_line l JOIN accounting.account a ON a.tenant_id=l.tenant_id AND a.id=l.account_id WHERE l.tenant_id=NEW.tenant_id AND l.journal_id=NEW.id AND (a.ledger_id<>NEW.ledger_id OR a.archived_at IS NOT NULL OR l.archived_at IS NOT NULL)) THEN RAISE EXCEPTION 'invalid ledger account'; END IF;
 IF NEW.reversed_journal_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM accounting.journal j WHERE j.tenant_id=NEW.tenant_id AND j.id=NEW.reversed_journal_id AND j.ledger_id=NEW.ledger_id AND j.status='POSTED' AND j.id<>NEW.id) THEN RAISE EXCEPTION 'invalid reversal source'; END IF;
 IF NEW.reversed_journal_id IS NOT NULL AND EXISTS(
   SELECT account_id,sum(debit_minor-credit_minor) FROM accounting.journal_line WHERE tenant_id=NEW.tenant_id AND journal_id IN (NEW.id,NEW.reversed_journal_id) GROUP BY account_id HAVING sum(debit_minor-credit_minor)<>0
 ) THEN RAISE EXCEPTION 'reversal does not offset source accounts'; END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER validate_post BEFORE INSERT OR UPDATE OF status ON accounting.journal FOR EACH ROW EXECUTE FUNCTION app_private.check_journal_post();
CREATE FUNCTION app_private.post_journal(t uuid,j uuid,expected integer) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE row accounting.journal%ROWTYPE;
BEGIN
 SELECT * INTO STRICT row FROM accounting.journal WHERE tenant_id=t AND id=j FOR UPDATE;
 PERFORM app_private.require_permission(t,row.scope_id,'accounting.journal.post');
 PERFORM app_private.require_policy(t,'FINANCIAL_POSTING');
 IF row.status<>'DRAFT' OR row.version<>expected OR row.archived_at IS NOT NULL OR row.maker_id=app_private.actor() THEN RAISE EXCEPTION 'journal not eligible for posting'; END IF;
 UPDATE accounting.journal SET status='POSTED',checker_id=app_private.actor(),posted_at=clock_timestamp() WHERE tenant_id=t AND id=j;
END $$;

CREATE FUNCTION app_private.require_policy(t uuid,code_arg text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
BEGIN
 IF NOT EXISTS(SELECT 1 FROM compliance.policy p WHERE p.tenant_id=t AND p.code=code_arg AND p.status='ACTIVE' AND p.archived_at IS NULL AND p.effective_from<=now() AND (p.effective_to IS NULL OR p.effective_to>now())) THEN RAISE EXCEPTION 'policy gate closed: %',code_arg USING ERRCODE='55000'; END IF;
END $$;
CREATE FUNCTION app_private.check_master_reference() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE rid uuid; rs uuid; j jsonb:=to_jsonb(NEW); t uuid:=(j->>'tenant_id')::uuid; ok boolean;
BEGIN
 -- only applied to direct generic CRUD, not to privileged procedures or fixtures
 IF current_setting('role',true)<>'wholesale_runtime' AND EXISTS(SELECT 1 FROM pg_roles WHERE rolname=session_user AND (rolsuper OR rolbypassrls)) THEN RETURN NEW; END IF;
 IF NOT pg_has_role(session_user,'wholesale_runtime','MEMBER') THEN RETURN NEW; END IF;
 rid=(j->>TG_ARGV[2])::uuid; IF rid IS NULL THEN RETURN NEW; END IF;
 EXECUTE format('SELECT true,scope_id FROM %I.%I WHERE tenant_id=$1 AND id=$2 AND archived_at IS NULL',TG_ARGV[0],TG_ARGV[1]) INTO ok,rs USING t,rid;
 IF NOT coalesce(ok,false) OR NOT coalesce(app_private.can(t,rs,TG_ARGV[0]||'.'||TG_ARGV[1]||'.read'),false) THEN RAISE EXCEPTION 'inaccessible referenced record' USING ERRCODE='42501'; END IF;
 RETURN NEW;
END $$;

