-- Stock reserve serializes competing writers on the balance row. No client-side stock authority.
CREATE FUNCTION app_private.reserve_stock(t uuid,b uuid,l uuid,q numeric) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE st inventory.stock_balance%ROWTYPE; ln commerce.order_line%ROWTYPE; lot inventory.lot%ROWTYPE; oid uuid; existing inventory.reservation%ROWTYPE; booked numeric;
BEGIN
 SELECT * INTO STRICT ln FROM commerce.order_line WHERE tenant_id=t AND id=l FOR UPDATE;
 SELECT * INTO STRICT st FROM inventory.stock_balance WHERE tenant_id=t AND id=b FOR UPDATE;
 PERFORM app_private.require_permission(t,st.scope_id,'inventory.reservation.create');
 PERFORM app_private.require_permission(t,ln.scope_id,'commerce.order_line.read');
 SELECT * INTO existing FROM inventory.reservation WHERE tenant_id=t AND balance_id=b AND order_line_id=l;
 IF FOUND THEN IF existing.quantity=q AND existing.status='ACTIVE' THEN RETURN existing.id; END IF; RAISE EXCEPTION 'reservation conflict'; END IF;
 SELECT * INTO STRICT lot FROM inventory.lot WHERE tenant_id=t AND id=st.lot_id FOR SHARE;
 IF st.archived_at IS NOT NULL OR lot.archived_at IS NOT NULL OR lot.status<>'AVAILABLE' OR (lot.expiry_date IS NOT NULL AND lot.expiry_date<=current_date) OR lot.product_id<>ln.product_id OR q<=0 OR q<>round(q,6) THEN RAISE EXCEPTION 'ineligible stock'; END IF;
 IF NOT EXISTS(SELECT 1 FROM commerce.sales_order o JOIN inventory.warehouse w ON w.tenant_id=o.tenant_id AND w.owner_id=o.seller_id WHERE o.tenant_id=t AND o.id=ln.order_id AND w.id=st.warehouse_id AND lot.owner_id=o.seller_id AND o.status IN ('SUBMITTED','ACCEPTED')) THEN RAISE EXCEPTION 'seller or order mismatch'; END IF;
 SELECT coalesce(sum(quantity),0) INTO booked FROM inventory.reservation WHERE tenant_id=t AND order_line_id=l AND status='ACTIVE';
 IF booked+q>(ln.paid_qty+ln.bonus_qty)*ln.base_factor OR st.on_hand-st.reserved<q THEN RAISE EXCEPTION 'insufficient stock or excessive reservation'; END IF;
 UPDATE inventory.stock_balance SET reserved=reserved+q WHERE tenant_id=t AND id=b;
 INSERT INTO inventory.reservation(tenant_id,scope_id,balance_id,order_line_id,quantity) VALUES(t,st.scope_id,b,l,q) RETURNING id INTO oid; RETURN oid;
END $$;
CREATE FUNCTION app_private.release_stock(t uuid,r uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE rec inventory.reservation%ROWTYPE;
BEGIN
 SELECT * INTO STRICT rec FROM inventory.reservation WHERE tenant_id=t AND id=r;
 -- same order-line -> balance -> reservation lock order as reserve_stock
 PERFORM 1 FROM commerce.order_line WHERE tenant_id=t AND id=rec.order_line_id FOR UPDATE;
 PERFORM 1 FROM inventory.stock_balance WHERE tenant_id=t AND id=rec.balance_id FOR UPDATE;
 SELECT * INTO STRICT rec FROM inventory.reservation WHERE tenant_id=t AND id=r FOR UPDATE;
 PERFORM app_private.require_permission(t,rec.scope_id,'inventory.reservation.release');
 IF rec.status='RELEASED' THEN RETURN; END IF;
 IF rec.status<>'ACTIVE' THEN RAISE EXCEPTION 'reservation not active'; END IF;
 UPDATE inventory.stock_balance SET reserved=reserved-rec.quantity WHERE tenant_id=t AND id=rec.balance_id;
 UPDATE inventory.reservation SET status='RELEASED' WHERE tenant_id=t AND id=r;
END $$;
-- Credit commitments serialized by facility. All facility-changing procedures must use the same lock.
CREATE FUNCTION app_private.commit_credit(t uuid,f uuid,o uuid,amount bigint) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE fac credit.facility%ROWTYPE; ord commerce.sales_order%ROWTYPE; old credit.commitment%ROWTYPE; exposure numeric; rid uuid;
BEGIN
 SELECT * INTO STRICT fac FROM credit.facility WHERE tenant_id=t AND id=f FOR UPDATE;
 PERFORM app_private.require_permission(t,fac.scope_id,'credit.commitment.create');
 PERFORM app_private.require_policy(t,'TRADE_CREDIT');
 SELECT * INTO STRICT ord FROM commerce.sales_order WHERE tenant_id=t AND id=o FOR UPDATE;
 SELECT * INTO old FROM credit.commitment WHERE tenant_id=t AND order_id=o;
 IF FOUND THEN IF old.facility_id=f AND old.amount_minor=amount AND old.status='ACTIVE' THEN RETURN old.id; END IF; RAISE EXCEPTION 'credit commitment conflict'; END IF;
 IF fac.status<>'ACTIVE' OR fac.archived_at IS NOT NULL OR (fac.expires_at IS NOT NULL AND fac.expires_at<=now()) OR ord.buyer_id<>fac.buyer_id OR ord.seller_id<>fac.creditor_id OR ord.status NOT IN ('SUBMITTED','ACCEPTED') OR amount<=0 OR amount>ord.total_minor THEN RAISE EXCEPTION 'credit not eligible'; END IF;
 IF NOT EXISTS(SELECT 1 FROM organizations.retailer_profile p WHERE p.tenant_id=t AND p.party_id=fac.buyer_id AND p.kyc_status='APPROVED' AND p.archived_at IS NULL) THEN RAISE EXCEPTION 'retailer not approved'; END IF;
 IF fac.overdue_block AND EXISTS(SELECT 1 FROM credit.receivable WHERE tenant_id=t AND facility_id=f AND due_at<now() AND outstanding_minor>0) THEN RAISE EXCEPTION 'overdue credit'; END IF;
 SELECT (SELECT coalesce(sum(outstanding_minor),0) FROM credit.receivable WHERE tenant_id=t AND facility_id=f)+(SELECT coalesce(sum(amount_minor),0) FROM credit.commitment WHERE tenant_id=t AND facility_id=f AND status='ACTIVE') INTO exposure;
 IF exposure+amount>fac.limit_minor THEN RAISE EXCEPTION 'credit limit exceeded'; END IF;
 INSERT INTO credit.commitment(tenant_id,scope_id,facility_id,order_id,amount_minor) VALUES(t,fac.scope_id,f,o,amount) RETURNING id INTO rid; RETURN rid;
END $$;
-- The same tenant, seller, amount and currency must match; callback evidence is mandatory.
CREATE FUNCTION app_private.confirm_payment(t uuid,i uuid,w uuid,ref text,amount bigint) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE pi payments.payment_intent%ROWTYPE; wi payments.webhook_inbox%ROWTYPE; old payments.payment_transaction%ROWTYPE; rid uuid;
BEGIN
 SELECT * INTO STRICT pi FROM payments.payment_intent WHERE tenant_id=t AND id=i FOR UPDATE;
 PERFORM app_private.require_permission(t,pi.scope_id,'payments.payment_transaction.confirm');
 PERFORM app_private.require_policy(t,'DIGITAL_PAYMENTS');
 SELECT * INTO STRICT wi FROM payments.webhook_inbox WHERE tenant_id=t AND id=w FOR UPDATE;
 IF pi.merchant_id IS NULL OR wi.merchant_id<>pi.merchant_id OR wi.verified_intent_id IS DISTINCT FROM i OR wi.verified_provider_ref IS DISTINCT FROM ref OR wi.verified_amount_minor IS DISTINCT FROM amount OR wi.verified_currency IS DISTINCT FROM pi.currency OR NOT wi.verified OR wi.status NOT IN ('VERIFIED','PROCESSED') OR pi.amount_minor<>amount OR amount<=0 THEN RAISE EXCEPTION 'payment evidence mismatch'; END IF;
 IF NOT EXISTS(SELECT 1 FROM payments.merchant_account m JOIN payments.provider p ON p.id=m.provider_id JOIN commerce.sales_order o ON o.tenant_id=m.tenant_id AND o.seller_id=m.seller_id WHERE m.tenant_id=t AND m.id=pi.merchant_id AND p.status='ACTIVE' AND m.status='ACTIVE' AND o.id=pi.order_id) THEN RAISE EXCEPTION 'provider or seller disabled'; END IF;
 SELECT * INTO old FROM payments.payment_transaction WHERE tenant_id=t AND merchant_id=pi.merchant_id AND provider_ref=ref;
 IF FOUND THEN IF old.intent_id=i AND old.amount_minor=amount THEN RETURN old.id; END IF; RAISE EXCEPTION 'provider reference conflict'; END IF;
 IF pi.status<>'PENDING' OR wi.status<>'VERIFIED' THEN RAISE EXCEPTION 'payment already processed or not pending'; END IF;
 INSERT INTO payments.payment_transaction(tenant_id,scope_id,intent_id,merchant_id,provider_ref,amount_minor,currency,confirmed_at) VALUES(t,pi.scope_id,i,pi.merchant_id,ref,amount,pi.currency,clock_timestamp()) RETURNING id INTO rid;
 UPDATE payments.payment_intent SET status='CONFIRMED' WHERE tenant_id=t AND id=i;
 UPDATE payments.webhook_inbox SET status='PROCESSED' WHERE tenant_id=t AND id=w;
 INSERT INTO integrations.outbox(tenant_id,scope_id,event_type,aggregate_id,payload,dedupe_key) VALUES(t,pi.scope_id,'payment.confirmed.v1',rid,jsonb_build_object('transactionId',rid),'payment.confirmed:'||rid);
 RETURN rid;
END $$;
-- Provider verification is not performed by SQL: the trusted adapter must bind exact evidence fields.
-- Until Phase 5 adapter certification, the payment provider registry is DISABLED.
REVOKE ALL ON ALL FUNCTIONS IN SCHEMA app_private FROM PUBLIC;
GRANT EXECUTE ON FUNCTION app_private.can(uuid,uuid,text), app_private.tenant(), app_private.actor() TO wholesale_runtime;
GRANT EXECUTE ON FUNCTION app_private.post_journal(uuid,uuid,integer),app_private.reserve_stock(uuid,uuid,uuid,numeric),app_private.release_stock(uuid,uuid),app_private.commit_credit(uuid,uuid,uuid,bigint),app_private.confirm_payment(uuid,uuid,uuid,text,bigint) TO wholesale_runtime;
COMMIT;
